using AtlasPca;
using Xunit;

namespace AtlasPca.Corpus.Tests;

// Generated by gen-rim-c14n-differential.mjs: the canonical bytes xml-crypto 6.1.2 (the reference) gives for each document, replayed against AttestXml.Canonicalize.
public class RimC14nDifferentialTests
{
    const string Ds = "http://www.w3.org/2000/09/xmldsig#";

    static (string SignedInfo, string Root) Run(string xml)
    {
        var root = AttestXml.Parse(xml).Root!;
        var sig = root.ElementChildrenNs(Ds, "Signature")[0];
        var si = sig.ElementChildrenNs(Ds, "SignedInfo")[0];
        return (AttestXml.Canonicalize(si, si.Parent!.Scope(), null), AttestXml.Canonicalize(root, new Dictionary<string, string>(StringComparer.Ordinal), sig));
    }

    [Fact]
    public void DefaultNamespaceEverywhere()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" name=\"a\" tagId=\"t\"><Meta/><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" name=\"a\" tagId=\"t\"><Meta></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void PrefixedSignature()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" name=\"a\"><Meta/><ds:Signature xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><ds:SignedInfo><ds:X/></ds:SignedInfo></ds:Signature></SoftwareIdentity>");
        Assert.Equal("<ds:SignedInfo xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><ds:X></ds:X></ds:SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" name=\"a\"><Meta></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void PrefixDeclaredOnTheRoot()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><Meta/><ds:Signature><ds:SignedInfo><ds:X/></ds:SignedInfo></ds:Signature></SoftwareIdentity>");
        Assert.Equal("<ds:SignedInfo xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><ds:X></ds:X></ds:SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><Meta></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void DefaultNamespaceRedeclared()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\"><Meta xmlns=\"urn:other\"><a/></Meta><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\"><Meta xmlns=\"urn:other\"><a></a></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void RedundantPrefixDeclarationOnTheSignedElement()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:x=\"urn:x\"><Meta xmlns:x=\"urn:x\"><x:a/></Meta><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\" xmlns:x=\"urn:x\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:x=\"urn:x\"><Meta><x:a></x:a></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void MixedCasePrefixesAreOrderedByLocaleCompare()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:b=\"urn:b\" xmlns:A=\"urn:a\" xmlns:a=\"urn:aa\"><Meta/><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\" xmlns:a=\"urn:aa\" xmlns:A=\"urn:a\" xmlns:b=\"urn:b\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:a=\"urn:aa\" xmlns:A=\"urn:a\" xmlns:b=\"urn:b\"><Meta></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void AttributeOrderingWithNamespaces()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:b=\"urn:b\" xmlns:c=\"urn:c\" z=\"1\" b:y=\"2\" c:x=\"3\" a=\"4\"><Meta c:q=\"1\" b:q=\"2\"/><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\" xmlns:b=\"urn:b\" xmlns:c=\"urn:c\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:b=\"urn:b\" xmlns:c=\"urn:c\" a=\"4\" z=\"1\" b:y=\"2\" c:x=\"3\"><Meta b:q=\"2\" c:q=\"1\"></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void DefaultNamespaceUndeclared()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\"><Meta xmlns=\"\"><a/></Meta><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\"><Meta xmlns=\"\"><a></a></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void EscapesInTextAndAttributes()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" v=\"a&amp;b &lt;c&gt; &quot;q&quot;\"><Meta>x &amp; y &gt; z &#13;&#10; ]]&gt;</Meta><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" v=\"a&amp;b &lt;c> &quot;q&quot;\"><Meta>x &amp; y &gt; z &#xD;\n ]]&gt;</Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void PrefixedElementDeclaringTheDefaultNamespace()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\"><p:Meta xmlns=\"urn:u\" xmlns:p=\"urn:p\"><c/></p:Meta><Signature xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><SignedInfo><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"/></SignedInfo></Signature></SoftwareIdentity>");
        Assert.Equal("<SignedInfo xmlns=\"http://www.w3.org/2000/09/xmldsig#\"><CanonicalizationMethod Algorithm=\"http://www.w3.org/2006/12/xml-c14n11\"></CanonicalizationMethod></SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\"><p:Meta xmlns:p=\"urn:p\"><c xmlns=\"urn:u\"></c></p:Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void PrefixedAttributeOfAnUndeclaredLocalDeclaration()
    {
        var (si, root) = Run("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><Meta ds:a=\"1\"><Meta ds:b=\"2\"/></Meta><ds:Signature><ds:SignedInfo><ds:X ds:y=\"1\"/></ds:SignedInfo></ds:Signature></SoftwareIdentity>");
        Assert.Equal("<ds:SignedInfo xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><ds:X ds:y=\"1\"></ds:X></ds:SignedInfo>", si);
        Assert.Equal("<SoftwareIdentity xmlns=\"urn:swid\" xmlns:ds=\"http://www.w3.org/2000/09/xmldsig#\"><Meta ds:a=\"1\"><Meta ds:b=\"2\"></Meta></Meta></SoftwareIdentity>", root);
    }

    [Fact]
    public void APrefixRedeclaredToAnotherUriIsRefused()
    {
        Assert.Throws<AttestError>(() => AttestXml.Parse("<r:S xmlns:r=\"urn:one\"><r:M xmlns:r=\"urn:two\"/></r:S>"));
        Assert.Throws<AttestError>(() => AttestXml.Parse("<r xmlns:q=\"u\"><b xmlns:q=\"\"/></r>"));
        AttestXml.Parse("<r xmlns:q=\"u\"><b xmlns:q=\"u\"/></r>"); // the same URI again is harmless
    }

    [Fact]
    public void ANonAsciiPrefixIsRefusedBecauseItsLocaleOrderCannotBeReproduced()
    {
        Assert.Throws<AttestError>(() => AttestXml.Parse("<r xmlns:\u00e9=\"u\"/>"));
    }
}

